-- ALT zoom orientation test values. Keep these together so they are easy to tune after visual testing.
-- ALT-view angles are empirical per model family: TTS uses X=pitch, Y=yaw, Z=roll, but imported meshes have different local axes.
-- Current tuning: avatars and normal monster/discard bags are confirmed. Cities only need their top view rotated upright.
-- Special monster/discard meshes are kept independently tunable; normal monster bags also avoid the exact Y=1 ALT-view boundary.
CITY_ALT_VIEW_ANGLE={0, 180, 180}
AVATAR_ALT_VIEW_ANGLE={0, 180, 180}
MONSTER_BAG_ALT_VIEW_ANGLE={-90, 180, 0}
MONSTER_BAG_LOW_COUNT_ALT_VIEW_ANGLE={0, 180, 0} --11 or fewer tokens
RUIN_BAG_ALT_VIEW_ANGLE={90, 180, 270}
RUIN_BAG_LOW_COUNT_ALT_VIEW_ANGLE={0, 180, 180} --10 or fewer tokens; same top view, rotated upright
POSSESSED_BAG_ALT_VIEW_ANGLE={90, 180, 180}
ZIGGURAT_PYRAMID_BAG_ALT_VIEW_ANGLE={0, 180, 180}
DISCARD_BAG_ALT_VIEW_ANGLE={0, 180, 0}
DISCARD_BAG_HIGH_COUNT_ALT_VIEW_ANGLE={-90, 180, 0} --13 or more tokens
